#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <utility>
#include <vector>
using namespace std;

// 独立实现一：正向暴力。从 total=1 起逐个模拟 N 只小猫分鱼，第一个全程合法者即最小鱼数。
static long long fwd_expected(long long n, long long i) {
    for (long long total = 1; ; ++total) {
        long long cur = total;
        bool ok = true;
        for (long long c = 0; c < n; ++c) {
            if (cur < i) { ok = false; break; }
            long long rem = cur - i;
            if (rem % n != 0) { ok = false; break; }
            long long share = rem / n;
            if (share < 1) { ok = false; break; }
            cur = rem - share;
        }
        if (ok) return total;
    }
}

// 独立实现二：逆向枚举最后一只小猫拿走的份 k，逐轮整除检查。
static long long rev_expected(long long n, long long i) {
    for (long long k = 1; ; ++k) {
        long long ans = k * n + i;
        bool ok = true;
        for (long long step = 1; step < n; ++step) {
            if (ans % (n - 1) != 0) { ok = false; break; }
            ans = ans / (n - 1) * n + i;
        }
        if (ok) return ans;
    }
}

static bool check(const string& exe, long long n, long long i, long long want, int id) {
    const string inFile = "l3a12p1_input.txt", outFile = "l3a12p1_output.txt";
    {
        ofstream out(inFile);
        out << n << "\n" << i << "\n";
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    long long actual = -1;
    string extra;
    bool ok = code == 0 && (in >> actual) && !(in >> extra) && actual == want;
    if (!ok) {
        cout << "[FAIL] case " << id << ": n=" << n << " i=" << i << ", expected=" << want
             << ", actual=" << actual << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<pair<pair<long long, long long>, long long>> tests = {
        {{2, 1}, 7}, {{3, 1}, 25},          // PDF 样例
        {{1, 0}, 1}, {{2, 0}, 4},           // 边界：N=1、i=0
        {{3, 2}, 23}, {{4, 1}, 253}, {{4, 3}, 247},
        {{5, 2}, 3117}, {{6, 0}, 46656},
        {{7, 3}, 823525}, {{8, 5}, 16777181},
        {{9, 1}, 387420481}, {{9, 8}, 387420425}  // 边界：N、i 取上限附近
    };
    unsigned seed = 202312u;
    int id = static_cast<int>(tests.size());
    for (int trial = 0; trial < 10; ++trial) {
        seed = seed * 1664525u + 1013904223u;
        long long n = 1 + seed % 4;         // 小规模：正向暴力独立验证
        seed = seed * 1664525u + 1013904223u;
        long long i = seed % n;
        tests.push_back({{n, i}, fwd_expected(n, i)});
        ++id;
    }
    for (int trial = 0; trial < 6; ++trial) {
        seed = seed * 1664525u + 1013904223u;
        long long n = 5 + seed % 5;         // 大规模：逆向实现独立验证
        seed = seed * 1664525u + 1013904223u;
        long long i = seed % n;
        tests.push_back({{n, i}, rev_expected(n, i)});
        ++id;
    }
    int pass = 0;
    for (size_t t = 0; t < tests.size(); ++t)
        if (check(argv[1], tests[t].first.first, tests[t].first.second, tests[t].second, static_cast<int>(t + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

