#include <cstdlib>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

struct Item { long long x; string u1; string u2; };

// 独立实现：单位基数表 + 整数倍率换算
static long long base_of(const string& u) {
    if (u == "mm" || u == "mg") return 1;
    if (u == "m" || u == "g") return 1000;
    return 1000000;  // km / kg
}
static long long expected(const Item& it) {
    return it.x * base_of(it.u1) / base_of(it.u2);
}

static bool check(const string& exe, const vector<Item>& items, int id) {
    const string inFile = "l3a12p2_input.txt", outFile = "l3a12p2_output.txt";
    {
        ofstream out(inFile);
        out << items.size() << "\n";
        for (size_t k = 0; k < items.size(); ++k)
            out << items[k].x << " " << items[k].u1 << " = ? " << items[k].u2 << "\n";
    }
    string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream in(outFile);
    bool ok = code == 0;
    for (size_t k = 0; ok && k < items.size(); ++k) {
        long long ox = -1, oa = -1;
        string ou1, eq, ou2;
        if (!(in >> ox >> ou1 >> eq >> oa >> ou2)) { ok = false; break; }
        if (ox != items[k].x || ou1 != items[k].u1 || eq != "=" || ou2 != items[k].u2 || oa != expected(items[k])) ok = false;
    }
    string extraToken;
    if (ok && (in >> extraToken)) ok = false;  // 不允许多余输出
    if (!ok) {
        cout << "[FAIL] case " << id << ": first line x=" << items[0].x << " " << items[0].u1 << "->" << items[0].u2
             << ", expected0=" << expected(items[0]) << ", process status=" << code << '\n';
    }
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<vector<Item>> tests = {
        {{1, "km", "mm"}, {1, "m", "mm"}},  // PDF 样例 1
        {{100, "m", "mm"}, {1000, "km", "m"}, {20, "kg", "g"}, {200, "g", "mg"}, {0, "kg", "mg"}},  // PDF 样例 2
        {{0, "km", "mm"}, {0, "m", "mm"}, {0, "kg", "mg"}},  // 边界：x=0
        {{1000, "km", "mm"}, {1000, "kg", "mg"}},            // 边界：x 上限，答案 1e9
        {{1000, "m", "mm"}, {1000, "km", "m"}, {1000, "kg", "g"}, {1000, "g", "mg"}},
        {{7, "km", "m"}, {7, "m", "mm"}, {7, "km", "mm"}, {7, "kg", "g"}, {7, "g", "mg"}, {7, "kg", "mg"}}  // 全部六种题型
    };
    const char* u1s[] = {"km", "m", "kg", "g"};
    const char* u2len[] = {"mm", "m"};
    unsigned seed = 202312u;
    for (int trial = 0; trial < 8; ++trial) {
        vector<Item> items;
        int n = 3 + trial * 127 % 40;
        for (int k = 0; k < n; ++k) {
            seed = seed * 1664525u + 1013904223u;
            long long x = seed % 1001u;
            seed = seed * 1664525u + 1013904223u;
            int pick = seed % 6u;
            Item it;
            it.x = x;
            switch (pick) {
                case 0: it.u1 = "m";  it.u2 = "mm"; break;
                case 1: it.u1 = "km"; it.u2 = "mm"; break;
                case 2: it.u1 = "km"; it.u2 = "m";  break;
                case 3: it.u1 = "g";  it.u2 = "mg"; break;
                case 4: it.u1 = "kg"; it.u2 = "mg"; break;
                default: it.u1 = "kg"; it.u2 = "g"; break;
            }
            items.push_back(it);
        }
        tests.push_back(items);
    }
    (void)u1s; (void)u2len;
    int pass = 0;
    for (size_t t = 0; t < tests.size(); ++t)
        if (check(argv[1], tests[t], static_cast<int>(t + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
